//! CPI bindings for Opening Cross.
//!
//! Add this crate to an Anchor program to call `cross_core` and `cross_gate` with typed
//! accounts and arguments, read their accounts, and derive every PDA they use. The bindings
//! are generated by `declare_program!` from the IDLs shipped in `idls/`, which CI keeps
//! byte-identical to the programs' own IDLs.
//!
//! ```ignore
//! use opening_cross_cpi::cross_core;
//! cross_core::cpi::commit_order(
//!     CpiContext::new(cross_core_program, cross_core::cpi::accounts::CommitOrder { .. }),
//!     args,
//! )?;
//! ```
#![allow(unexpected_cfgs)]

use anchor_lang::prelude::*;

declare_program!(cross_core);
declare_program!(cross_gate);

/// PDA seeds and derivations, mirroring `cross_core::state` and `cross_gate`.
pub mod pda {
    use super::*;

    pub const PROTOCOL_SEED: &[u8] = b"protocol";
    pub const CROSS_SEED: &[u8] = b"cross";
    pub const BOOK_SEED: &[u8] = b"book";
    pub const SHARD_SEED: &[u8] = b"shard";
    pub const ORDER_SEED: &[u8] = b"order";
    pub const QUOTE_VAULT_SEED: &[u8] = b"quote_vault";
    pub const BASE_VAULT_SEED: &[u8] = b"base_vault";
    pub const GATE_CONFIG_SEED: &[u8] = b"config";
    pub const GATE_PASS_SEED: &[u8] = b"pass";

    fn core(seeds: &[&[u8]]) -> (Pubkey, u8) {
        Pubkey::find_program_address(seeds, &cross_core::ID)
    }

    pub fn protocol() -> (Pubkey, u8) {
        core(&[PROTOCOL_SEED])
    }
    pub fn cross(creator: &Pubkey, cross_id: u64) -> (Pubkey, u8) {
        core(&[CROSS_SEED, creator.as_ref(), &cross_id.to_le_bytes()])
    }
    pub fn book(cross: &Pubkey) -> (Pubkey, u8) {
        core(&[BOOK_SEED, cross.as_ref()])
    }
    pub fn shard(cross: &Pubkey, index: u8) -> (Pubkey, u8) {
        core(&[SHARD_SEED, cross.as_ref(), &[index]])
    }
    /// Which shard an order lands in: `sha256(owner ‖ nonce)` as a little-endian `u32`, modulo `shards`
    /// (the SDK's `shardIndexFor`; the program's `shard_of`).
    pub fn shard_index_for(owner: &Pubkey, nonce: u64, shards: u8) -> u8 {
        let h = solana_sha256_hasher::hashv(&[owner.as_ref(), &nonce.to_le_bytes()]).to_bytes();
        (u32::from_le_bytes([h[0], h[1], h[2], h[3]]) % u32::from(shards.max(1))) as u8
    }
    pub fn order(cross: &Pubkey, owner: &Pubkey, nonce: u64) -> (Pubkey, u8) {
        core(&[
            ORDER_SEED,
            cross.as_ref(),
            owner.as_ref(),
            &nonce.to_le_bytes(),
        ])
    }
    pub fn quote_vault(cross: &Pubkey) -> (Pubkey, u8) {
        core(&[QUOTE_VAULT_SEED, cross.as_ref()])
    }
    pub fn base_vault(cross: &Pubkey) -> (Pubkey, u8) {
        core(&[BASE_VAULT_SEED, cross.as_ref()])
    }
    pub fn gate_config(mint: &Pubkey) -> (Pubkey, u8) {
        Pubkey::find_program_address(&[GATE_CONFIG_SEED, mint.as_ref()], &cross_gate::ID)
    }
    pub fn gate_pass(mint: &Pubkey, owner: &Pubkey) -> (Pubkey, u8) {
        Pubkey::find_program_address(
            &[GATE_PASS_SEED, mint.as_ref(), owner.as_ref()],
            &cross_gate::ID,
        )
    }
}
